{
  "title": "The Rescue of Ruined Aldemar",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A small band gathers at dawn outside the fallen city.",
      "visual_description": "Four figures on a windswept ridge overlooking a skyline of broken towers and torn royal banners; pale dawn light, mist clinging to the rubble below.",
      "characters": ["Captain Ronnea", "Mapmaker Silv", "Wisp the Familiar", "Brann the Scout"]
    },
    {
      "scene_number": 2,
      "caption": "Silv unrolls the city map and marks the prison tower.",
      "visual_description": "Close shot of a weathered parchment map weighted by stones, ink-circled spires, gloved fingers tracing a route; firelight from a small camp lantern.",
      "characters": ["Mapmaker Silv", "Captain Ronnea"]
    },
    {
      "scene_number": 3,
      "caption": "Brann scouts the cracked castle gates.",
      "visual_description": "A cloaked scout pressed to a moss-eaten gate pillar, watching armored patrols pass through a half-collapsed portcullis; long shadows across cobblestone.",
      "characters": ["Brann the Scout"]
    },
    {
      "scene_number": 4,
      "caption": "The team slips through a side breach in the wall.",
      "visual_description": "Three figures squeezing through a jagged gap in the curtain wall, ivy and rubble framing them, a glowing wisp lighting the dark interior.",
      "characters": ["Captain Ronnea", "Brann the Scout", "Wisp the Familiar"]
    },
    {
      "scene_number": 5,
      "caption": "Frightened townspeople warn of patrols and curses.",
      "visual_description": "A hooded woman and a thin baker clutching a child in a shadowed doorway, gesturing toward a smoking tower, tattered royal banners hanging above.",
      "characters": ["Goodwife Mera", "Baker Tomwin", "Captain Ronnea"]
    },
    {
      "scene_number": 6,
      "caption": "An armored patrol marches through the market square.",
      "visual_description": "Rank of black-plated soldiers with spears crossing a ruined fountain plaza; broken stalls, scattered fruit, the heroes pressed flat behind an overturned cart.",
      "characters": ["Sergeant Halric", "Captain Ronnea", "Brann the Scout"]
    },
    {
      "scene_number": 7,
      "caption": "Rumors swirl of a dragon nesting in the keep.",
      "visual_description": "A nervous old herald whispering by torchlight beside a smoke-streaked statue, hands miming wings; distant orange glow over the rooftops.",
      "characters": ["Herald Oswin", "Mapmaker Silv"]
    },
    {
      "scene_number": 8,
      "caption": "Wisp leads them around the cursed tower.",
      "visual_description": "A spiral tower wreathed in violet mist, runes flickering on its stones; a small luminous familiar darting ahead while the party arcs wide around it.",
      "characters": ["Wisp the Familiar", "Captain Ronnea", "Mapmaker Silv", "Brann the Scout"]
    },
    {
      "scene_number": 9,
      "caption": "They find a sleepy gatekeeper guarding a magic door.",
      "visual_description": "A round official slumped on a stool, keys dangling, snoring before an arched door etched with glowing sigils in a vaulted corridor.",
      "characters": ["Warden Pibble", "Brann the Scout"]
    },
    {
      "scene_number": 10,
      "caption": "Silv deciphers the door's sigils.",
      "visual_description": "Mapmaker tracing glowing runes in the air with chalk-dusted fingers, blue light reflecting on her spectacles, the door humming awake.",
      "characters": ["Mapmaker Silv", "Wisp the Familiar"]
    },
    {
      "scene_number": 11,
      "caption": "Inside the dungeon, they find the captive prince.",
      "visual_description": "A gaunt young man in tattered velvet behind iron bars, chains on his wrists, looking up as torchlight spills across his face.",
      "characters": ["Prince Aldric", "Captain Ronnea"]
    },
    {
      "scene_number": 12,
      "caption": "Brann picks the lock as a patrol approaches.",
      "visual_description": "Hands working a slim pick in a heavy iron lock, sweat on the brow, the orange flicker of approaching torchlight at the end of a stone corridor.",
      "characters": ["Brann the Scout", "Prince Aldric"]
    },
    {
      "scene_number": 13,
      "caption": "Sergeant Halric corners them in the great hall.",
      "visual_description": "Shafts of moonlight through a shattered rose window onto a cracked marble floor; the armored sergeant raising a sword as the party fans out beneath fallen banners.",
      "characters": ["Sergeant Halric", "Captain Ronnea", "Prince Aldric", "Brann the Scout"]
    },
    {
      "scene_number": 14,
      "caption": "Wisp blinds the patrol with a burst of light.",
      "visual_description": "A small familiar exploding into white radiance mid-air, soldiers shielding their eyes, the heroes already turning to flee through a side arch.",
      "characters": ["Wisp the Familiar", "Sergeant Halric", "Captain Ronnea"]
    },
    {
      "scene_number": 15,
      "caption": "A real dragon stirs atop the keep.",
      "visual_description": "Massive scaled shape uncoiling around a broken spire under a bruised sky, one molten eye opening, embers drifting; tiny figures fleeing along a rooftop below.",
      "characters": ["Vaergoth the Dragon", "Prince Aldric", "Captain Ronnea"]
    },
    {
      "scene_number": 16,
      "caption": "The party sprints through narrow alleys toward the river.",
      "visual_description": "Dynamic low-angle of running figures in moonlit alley, dragonfire glow behind silhouetting them, scattered straw and rolling barrels in their wake.",
      "characters": ["Captain Ronnea", "Prince Aldric", "Mapmaker Silv", "Brann the Scout", "Wisp the Familiar"]
    },
    {
      "scene_number": 17,
      "caption": "They cross the crumbling bridge as stones fall behind them.",
      "visual_description": "A long stone bridge over a black river, sections collapsing into the water, the party mid-run with cloaks streaming, the dragon's shadow stretching over the span.",
      "characters": ["Captain Ronnea", "Prince Aldric", "Mapmaker Silv", "Brann the Scout", "Wisp the Familiar", "Vaergoth the Dragon"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far bank, they look back at the burning city.",
      "visual_description": "Five figures on a grassy bluff at dawn, silhouetted against distant smoke and a tiny circling dragon over broken towers; the prince's hand on the captain's shoulder.",
      "characters": ["Captain Ronnea", "Prince Aldric", "Mapmaker Silv", "Brann the Scout", "Wisp the Familiar"]
    }
  ]
}

